pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };

    // Penalize residual gaps that are unlikely to be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 180.0 + 12.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 35.0 + 3.0 * (20.0 - post_residual as f64);
    } else if post_residual > 0 {
        score += 0.08 * post_residual as f64;
    }

    // Reward exact closure and excellent utilization.
    if post_residual == 0 {
        score -= 130.0;
    } else if item_size >= 45 {
        score -= 18.0;
    } else if post_residual <= item_size {
        score -= 10.0;
    }

    // Opening a new bin is preferable to leaving a very poor, nearly unusable gap.
    if bin_residual == bin_capacity {
        score -= 25.0;
        score += 0.35 * open_bins_count as f64;
    } else {
        // More open bins imply stronger pressure to consolidate items.
        score += 2.2 * open_bins_count as f64;
    }

    // Prefer placements leaving room near the mean residual profile.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.045 * deviation;

    // Look-ahead: avoid consuming space needed by the next item when this
    // placement would strand a small remainder.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 22.0;
        } else if post_residual == next_item_size {
            score -= 28.0;
        }
        if post_residual > 0 && post_residual < 10 && next_item_size < 10 {
            score += 45.0;
        }
    }

    // If this is the only fitting bin, place here rather than open another bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Slightly favor tighter bins, with reduced pressure near the end.
    let tightness = if bin_capacity > 0 {
        item_size as f64 / bin_capacity as f64
    } else {
        0.0
    };
    score -= 20.0 * tightness * (1.0 - 0.25 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let item = item_size as f64;
    let capacity = bin_capacity as f64;
    let residual = bin_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };

    let utilization_after = if capacity > 0.0 {
        1.0 - residual / capacity
    } else {
        0.0
    };
    let waste_ratio = if capacity > 0.0 {
        post_residual as f64 / capacity
    } else {
        0.0
    };

    score += 0.85 * waste_ratio;
    score -= 1.30 * utilization_after;

    if post_residual == 0 {
        score -= 14.0;
    } else if post_residual < next && next > 0.0 {
        score += 2.2 * (next - post_residual as f64).min(30.0);
    } else if post_residual <= 15 && post_residual > 0 {
        score += 0.6 * (15.0 - post_residual as f64);
    }

    if next > 0.0 {
        let lookahead_fit = post_residual >= next;
        score -= if lookahead_fit { 2.8 } else { 0.0 };
        let effective_residual = post_residual as f64 + next;
        let harmony = (1.0 - (effective_residual / capacity).min(1.0)).max(0.0);
        score -= 0.55 * harmony;
    }

    let mean_penalty = if open_bins_count > 0 {
        (mean_residual - post_residual as f64).clamp(-40.0, 40.0)
    } else {
        0.0
    };
    score -= 0.045 * mean_penalty;

    if fitting_bins_count <= 1 && !is_new_bin {
        score += 3.0;
    }

    if is_new_bin {
        score += 7.5;
        score += 5.0 * (1.0 - progress);
        score -= 2.0 * (open_bins_count as f64).sqrt();
    } else {
        score += 0.35 * (open_bins_count as f64).sqrt();
        let scarcity = (fitting_bins_count as f64).recip();
        score -= 1.2 * scarcity;
    }

    let future_pressure = if total_items > step_index {
        (total_items - step_index) as f64 / total_items as f64
    } else {
        0.0
    };
    score += 2.0 * future_pressure * (post_residual as f64 / capacity);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let progress = if total_items == 0 {
        0.0
    } else {
        step_index as f64 / total_items as f64
    };
    let mean_gap = (mean_residual - item as f64).clamp(0.0, capacity);
    let fit_ratio = if bin_capacity == 0 {
        0.0
    } else {
        bin_residual as f64 / capacity
    };

    // Prefer compact fits and bins whose remaining space closely matches
    // the immediate lookahead item.
    score -= 0.65 * item;
    score -= 0.22 * mean_gap;
    score -= 4.0 * (post_residual as f64 / capacity).powi(2);
    score -= 2.0 * fit_ratio.powi(2);

    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual >= next {
            let exactness = 1.0 - (post_residual as f64 - next).abs() / capacity;
            score -= 16.0 * exactness;
        } else {
            let loss = next - post_residual as f64;
            score += 0.28 * loss;
            if post_residual == 0 {
                score += 8.0;
            }
        }
        // A near-exact two-item match is especially valuable.
        if post_residual == next {
            score -= 12.0;
        }
    } else {
        score += 0.10 * post_residual as f64;
    }

    // With only one fitting bin, avoid consuming it unless the fit is
    // promising or opening another bin would be materially better.
    if fitting_bins_count == 1 {
        score += 6.0;
        if post_residual == 0 {
            score += 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Later in the stream, preserving flexible residual space matters more;
    // early on, aggressively fill bins and make room for future items.
    score += 7.0 * progress * (post_residual as f64 / capacity);
    score -= 2.5 * (1.0 - progress) * (post_residual as f64 / capacity);

    // New-bin candidate: charge a modest, progress-sensitive opening cost,
    // but permit opening when existing bins are poor and lookahead benefits.
    if bin_residual == bin_capacity {
        score += 18.0;
        score -= 8.0 * progress;
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
        if next_item_size == 0 {
            score -= 4.0;
        }
    }

    // Avoid excessive fragmentation: a residual that cannot host the next
    // known item is penalized more as the stream advances.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 5.0 * progress * (next_item_size - post_residual) as f64;
    }

    // Small preference for consolidating into fewer bins once several exist.
    if open_bins_count > 1 {
        score += 0.8 * (open_bins_count as f64 - 1.0).min(8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let dead_space_threshold = item_size as f64;
    if (post_residual as f64) < dead_space_threshold {
        score += (dead_space_threshold - post_residual as f64) * 3.0;
    }

    if post_residual == 0 {
        score -= 8.0;
    } else if post_residual < next_item_size as f64 && next_item_size != 0 {
        score += (next_item_size as f64 - post_residual as f64) * 2.0;
    }

    let pressure = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += open_bins_count as f64 * (0.35 + 0.65 * pressure);

    if fitting_bins_count <= 1 {
        score -= 4.0;
    }

    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual.max(0.0) * 0.25;
    } else {
        score -= (bin_capacity - bin_residual) as f64 * 0.015;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Small residuals are especially difficult to reuse when future items are
    // generally larger than the gaps they leave behind.
    let dead_space_threshold = (item_size as f64 * 0.45).max(8.0);
    if (post_residual as f64) < dead_space_threshold {
        score += (dead_space_threshold - post_residual as f64) * 2.5;
    }

    // Reward an exact fill and strongly prefer placements that consume the
    // existing residual instead of leaving a potentially unusable gap.
    if post_residual == 0 {
        score -= 12.0;
    } else {
        score -= (item_size as f64 / bin_residual.max(1) as f64) * 2.0;
    }

    // Preserve room for the immediate lookahead item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.35;
    }

    // When few bins can accept this item, use the existing bin rather than
    // opening another one, except for genuinely poor fits.
    if fitting_bins_count <= 1 {
        score -= 9.0;
    } else {
        score += (fitting_bins_count as f64).ln() * 0.35;
    }

    // More open bins increase the opportunity cost of consuming a good bin.
    score += open_bins_count as f64 * 0.025;

    // Near the end of the stream, favor compactness and exact closure.
    let progress = if total_items == 0 {
        1.0
    } else {
        step_index as f64 / total_items as f64
    };
    score += (1.0 - progress) * 0.75;
    score -= (post_residual as f64 / bin_capacity.max(1) as f64) * 1.5;

    // Keep the score centered around the post-placement residual for callers
    // that interpret lower values as stronger placement preference.
    score += mean_residual * 0.01;
    score
}

