    }

    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 6.0;

    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score -= pressure * 2.0;

    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    let scarcity = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= scarcity * 3.0;

    if bin_residual == bin_capacity {
        score += 25.0;
    }

    let lookahead_value = if next_item_size > 0 {
        (next_item_size as f64 / bin_capacity as f64) * 4.0
    } else {
        0.0
    };
    score -= lookahead_value;

    score += (step_index as f64 / total_items.max(1) as f64) * 0.5;

    score
}
